/**
 * Оператор, чей префикс совпадает с началом номера. Если не совпал ничей,
 * номер отдаётся нейтральному перевозчику: приписать его случайному бренду
 * было бы враньём в интерфейсе.
 */
export function pickOperatorForDigits(country: Country, digits: string): string {
  for (const operatorId of country.operators) {
    const prefixes = OPERATOR_PREFIXES[operatorId] ?? [];
    if (prefixes.some((prefix) => digits.startsWith(prefix))) return operatorId;
  }
  const carrier = country.operators.find(
    (operatorId) => (OPERATOR_PREFIXES[operatorId] ?? []).length === 0,
  );
  return carrier ?? country.operators[0];
}

