// language: TypeScript, file: frontend/src/App.tsx
// Точка сборки: главный экран, экраны разделов и модальные окна.
// Никаких пустых переходов — каждый пункт меню ведёт на работающий экран
// либо на честную заглушку с описанием того, что появится позже.

import { useCallback, useEffect, useState } from 'react';
import { useGame } from './hooks/useGame';
import { HomeScreen } from './screens/HomeScreen';
import { CollectionScreen } from './screens/CollectionScreen';
import { NumberScreen } from './screens/NumberScreen';
import { AdminScreen } from './screens/AdminScreen';
import {
  HistoryScreen,
  ProfileScreen,
  QuestsScreen,
  RatingScreen,
  RulesScreen,
  SettingsScreen,
  ShopScreen,
  SoonScreen,
} from './screens/InfoScreens';
import { MenuDrawer, type MenuTarget } from './components/MenuDrawer';
import { TariffModal } from './components/TariffModal';
import { RoamingModal } from './components/RoamingModal';
import { ChancesModal } from './components/ChancesModal';
import { ResultOverlay } from './components/ResultOverlay';
import { initTelegram } from './telegram';

/** Экраны, которые уже работают. Разделы без экрана перечислены в SOON_SCREENS. */
type View = MenuTarget | 'number';

const SOON_SCREENS: Partial<Record<View, { title: string; note: string }>> = {
  roulette: {
    title: 'Рулетка',
    note: 'Колесо с бесплатными и платными прокрутами: билеты на Элит, бонусы удачи и скидки на выпуск.',
  },
  skills: {
    title: 'Навыки',
    note: 'Дерево навыков: снижение цены выпуска, повышение шанса редких категорий, ускорение опыта.',
  },
  market: {
    title: 'Рынок',
    note: 'Витрина номеров от игроков: лоты, цены, покупка за игровую валюту. Требует серверного учёта владения.',
  },
  auction: {
    title: 'Аукцион',
    note: 'Ставки на редкие номера с таймером и историей торгов.',
  },
  deals: {
    title: 'Сделки',
    note: 'Активные обмены и передача номеров между игроками с подтверждением обеих сторон.',
  },
  phones: {
    title: 'Телефоны',
    note: 'Каталог моделей и оформлений карточки номера.',
  },
  friends: {
    title: 'Друзья',
    note: 'Список друзей и реферальная ссылка с наградой за приглашённых игроков.',
  },
  promo: {
    title: 'Промокод',
    note: 'Ввод промокода и начисление награды. Проверка кода выполняется на сервере.',
  },
  channel: {
    title: 'Канал',
    note: 'Новости игры, анонсы ивентов и розыгрышей.',
  },
  checker: {
    title: 'Проверка номера',
    note: 'Разбор любого игрового номера: очки узора, оценка и место в коллекции.',
  },
};

export function App() {
  const game = useGame();
  const [view, setView] = useState<View>('home');
  const [drawer, setDrawer] = useState(false);
  const [overlay, setOverlay] = useState<'tariff' | 'roaming' | 'chances' | null>(null);
  const [openNumberId, setOpenNumberId] = useState<string | null>(null);
  const [blocked, setBlocked] = useState<View | null>(null);

  useEffect(() => {
    initTelegram();
  }, []);

  const go = useCallback((target: View) => {
    setDrawer(false);
    if (SOON_SCREENS[target]) {
      setBlocked(target);
      setView('home');
      return;
    }
    setBlocked(null);
    setView(target);
  }, []);

  const openNumber = useCallback((id: string) => {
    setOpenNumberId(id);
    setView('number');
    game.dismissDrop();
  }, [game]);

  const activeNumber = openNumberId
    ? game.state.numbers.find((number) => number.id === openNumberId) ?? null
    : null;

  // Последний выпуск показываем на главной карточке, как в референсе.
  const lastNumber = game.dropped ?? game.state.numbers[0] ?? null;

  return (
    <>
      {/* Заставка закрывает пустоту, пока проверяется доступность сервера. */}
      {game.mode === 'checking' && (
        <div className="splash">
          <div className="splash__mark">
            <span className="splash__chip" />
          </div>
          <div className="splash__title">Циферки</div>
          <div className="splash__hint">Собираем номера…</div>
        </div>
      )}

      {/* Ключ по экрану: при переходе содержимое въезжает заново. */}
      <div className="screen-enter" key={`${view}:${blocked ?? ''}:${openNumberId ?? ''}`}>
        {view === 'home' && (
          <HomeScreen
            game={game}
            lastNumber={lastNumber}
            onOpenMenu={() => setDrawer(true)}
            onOpenTariff={() => setOverlay('tariff')}
            onOpenRoaming={() => setOverlay('roaming')}
            onOpenCollection={() => go('collection')}
            onOpenNumber={openNumber}
          />
        )}

        {view === 'collection' && (
          <CollectionScreen
            game={game}
            onBack={() => setView('home')}
            onOpenNumber={openNumber}
          />
        )}

        {view === 'number' && activeNumber && (
          <NumberScreen
            game={game}
            number={activeNumber}
            onBack={() => setView(openNumberId && game.state.numbers.length > 0 ? 'collection' : 'home')}
          />
        )}

        {view === 'history' && <HistoryScreen game={game} onBack={() => go('home')} />}
        {view === 'profile' && <ProfileScreen game={game} onBack={() => go('home')} />}
        {view === 'quests' && <QuestsScreen game={game} onBack={() => go('home')} />}
        {view === 'rating' && <RatingScreen game={game} onBack={() => go('home')} />}
        {view === 'shop' && <ShopScreen game={game} onBack={() => go('home')} />}
        {view === 'rules' && <RulesScreen game={game} onBack={() => go('home')} />}
        {view === 'settings' && <SettingsScreen game={game} onBack={() => go('home')} />}
        {view === 'admin' && <AdminScreen game={game} onBack={() => go('home')} />}

        {view === 'home' && blocked && SOON_SCREENS[blocked] && (
          <SoonScreen
            game={game}
            onBack={() => setBlocked(null)}
            title={SOON_SCREENS[blocked]!.title}
            note={SOON_SCREENS[blocked]!.note}
          />
        )}
      </div>

      {drawer && <MenuDrawer game={game} onClose={() => setDrawer(false)} onGo={go} />}

      {overlay === 'tariff' && (
        <TariffModal
          selected={game.state.selectedTariff}
          luck={game.luck}
          balance={game.state.player.balance}
          tickets={game.state.player.tickets}
          onPick={game.chooseTariff}
          onOpenChances={() => setOverlay('chances')}
          onClose={() => setOverlay(null)}
        />
      )}

      {overlay === 'roaming' && (
        <RoamingModal
          selected={game.state.selectedCountry}
          onPick={game.chooseCountry}
          onCustom={() => {
            setOverlay(null);
            setBlocked('checker');
          }}
          onClose={() => setOverlay(null)}
        />
      )}

      {overlay === 'chances' && (
        <ChancesModal
          tariffId={game.state.selectedTariff}
          luck={game.luck}
          onPickTariff={game.chooseTariff}
          onClose={() => setOverlay(null)}
        />
      )}

      {game.dropped && view === 'home' && (
        <ResultOverlay
          number={game.dropped}
          onClose={game.dismissDrop}
          onOpen={() => openNumber(game.dropped!.id)}
        />
      )}

      {game.toasts.map((toast) => (
        <div
          key={toast.id}
          className={`toast ${toast.kind === 'error' ? 'toast--error' : ''}`}
        >
          {toast.text}
        </div>
      ))}
    </>
  );
}
